/**
 * Query helpers + formatters for the `/benchmarks` page.
 *
 * The data shapes are the single source of truth generated by Ossido from the
 * Rust `#[Type]`/`#[Props]` structs in `src/routes/benchmarks/page.rs` (exported
 * from `@ossido-labs/ossido/types`). This module re-exports them and adds small
 * lookups/formatters so the page stays declarative. There is no committed data
 * snapshot: the handler fetches it at build time (static SSG).
 */
import type {
  BenchMemoryFile,
  BenchMemoryRow,
  BenchResult,
  BenchResultsFile,
  BenchStreaming,
} from '@ossido-labs/ossido/types';

export type {
  BenchEnvironment,
  BenchMemoryFile,
  BenchMemoryRow,
  BenchResult,
  BenchResultsFile,
  BenchScenario,
  BenchStreaming,
  BenchmarksProps,
} from '@ossido-labs/ossido/types';

/** The two frameworks and threading modes recorded in every run. */
export type Framework = 'ossido' | 'next';
export type Mode = 'single' | 'multi';

/** Throughput/latency row for a scenario in a given framework + threading mode. */
export function resultFor(
  results: BenchResultsFile,
  scenario: string,
  framework: Framework,
  mode: Mode,
): BenchResult | undefined {
  return results.results.find(
    (r) =>
      r.scenario === scenario && r.framework === framework && r.mode === mode,
  );
}

/** Streaming-SSR probe for a framework + threading mode. */
export function streamingFor(
  results: BenchResultsFile,
  framework: Framework,
  mode: Mode,
): BenchStreaming | undefined {
  return results.streaming.find(
    (s) => s.framework === framework && s.mode === mode,
  );
}

/** Memory-sweep row for a framework at a parallelism level. */
export function memoryFor(
  memory: BenchMemoryFile | null | undefined,
  framework: Framework,
  parallelism: number,
): BenchMemoryRow | undefined {
  return memory?.results.find(
    (r) => r.framework === framework && r.parallelism === parallelism,
  );
}

/** `a` relative to `b`, e.g. 2157 / 581 -> "3.7×". */
export function ratio(a: number, b: number): string {
  if (!b) return '-';
  const r = a / b;
  return `${r >= 10 ? Math.round(r) : r.toFixed(1)}×`;
}

/** Thousands-separated integer (req/s, MB, etc.). */
export function formatNum(n: number): string {
  return Math.round(n).toLocaleString('en-US');
}

/** Milliseconds with sensible precision (sub-10ms keeps one decimal). */
export function formatMs(n: number): string {
  return n < 10 ? n.toFixed(1) : formatNum(n);
}
